target.css:
:root {
  --ink: #18334a;
  --indigo: #2457a6;
  --pale-indigo: #e8f0ff;
  --paper: #ffffff;
  --line: #c9d8e8;
  --muted: #63788d;
  --success-bg: #e1f3e9;
  --success-ink: #237451;
}

.slot-card {
  box-sizing: border-box;
  width: 480px;
  overflow: hidden;
  color: var(--ink);
  background: var(--paper);
  border: 1px solid var(--line);
  border-radius: 16px;
}

.slot-header {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  padding: 16px 18px 14px;
  border-bottom: 1px solid var(--line);
}

.eyebrow {
  margin: 0 0 4px;
  color: var(--muted);
  font-size: 12px;
  font-weight: 700;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}

h1 {
  margin: 0;
  font-size: 22px;
  line-height: 1.1;
}

.status {
  padding: 5px 9px;
  color: var(--success-ink);
  background: var(--success-bg);
  border-radius: 999px;
  font-size: 12px;
  font-weight: 700;
}

.slot-details {
  display: flex;
  gap: 16px;
  padding: 14px 18px;
}

.date-tile {
  display: flex;
  flex: 0 0 76px;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  min-height: 82px;
  color: var(--indigo);
  background: var(--pale-indigo);
  border-radius: 12px;
}

.month,
.day {
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 0.07em;
}

.date-tile strong {
  font-size: 30px;
  line-height: 0.95;
}

.detail-list {
  display: grid;
  flex: 1;
  gap: 6px;
  margin: 0;
  padding: 0;
  list-style: none;
}

.detail-list li {
  display: flex;
  justify-content: space-between;
  gap: 18px;
  font-size: 14px;
}

.detail-list span {
  color: var(--muted);
}

.slot-footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 11px 18px;
  background: var(--pale-indigo);
}

.slot-footer p {
  margin: 0;
  color: var(--muted);
  font-size: 12px;
}

button {
  padding: 7px 12px;
  color: var(--paper);
  background: var(--indigo);
  border: 0;
  border-radius: 8px;
  font-size: 13px;
  font-weight: 700;
}

